void comb(int i, int rem, vector<int>& c, vector<int>& cur, vector<vector<int>>& out){
    if (rem == 0) { out.push_back(cur); return; }
    for (int j = i; j < c.size() && c[j] <= rem; j++) {
        if (j > i && c[j] == c[j-1]) continue;   // ← the killer line
        cur.push_back(c[j]);
        comb(j + 1, rem - c[j], c, cur, out);     // forward-only: each index once
        cur.pop_back();
    }
}

void perm(int i, vector<int>& a, vector<vector<int>>& out){
    if (i == a.size()) { out.push_back(a); return; }
    for (int j = i; j < a.size(); j++) {
        swap(a[i], a[j]);       // choose j as this slot's occupant
        perm(i + 1, a, out);
        swap(a[i], a[j]);       // restore
    }
}

