void combSum2Rec(const vector<int>& cand, int start, int target,
                 vector<int>& cur, vector<vector<int>>& out) {
    if (target == 0) { out.push_back(cur); return; }
    for (int i = start; i < (int)cand.size(); ++i) {
        if (i > start && cand[i] == cand[i - 1]) continue;   // SKIP LINE
        if (cand[i] > target) break;                          // sorted: no point continuing
        cur.push_back(cand[i]);
        combSum2Rec(cand, i + 1, target - cand[i], cur, out); // i+1: each element ONCE
        cur.pop_back();
    }
}

