def combination_sum2(candidates: list, target: int) -> list:
    cand = sorted(candidates)      # MANDATORY: the skip line needs equals adjacent
    out, cur = [], []

    def rec(start, remaining):
        if remaining == 0:
            out.append(cur[:])
            return
        for i in range(start, len(cand)):
            if i > start and cand[i] == cand[i - 1]:
                continue                    # SKIP LINE
            if cand[i] > remaining:
                break                       # sorted: nothing further can fit
            cur.append(cand[i])
            rec(i + 1, remaining - cand[i])  # i+1: each element used ONCE
            cur.pop()

    rec(0, target)
    return out

