    for (int i = start; i < (int)a.size(); ++i) {
        if (i > start && a[i] == a[i - 1]) continue;   // same skip line
        cur.push_back(a[i]);
        subsetsWithDupRec(a, i + 1, cur, out);
        cur.pop_back();
    }
}

