void permuteUniqueRec(vector<int>& a, vector<bool>& used,
                      vector<int>& cur, vector<vector<int>>& out) {
    if (cur.size() == a.size()) { out.push_back(cur); return; }
    for (int i = 0; i < (int)a.size(); ++i) {
        if (used[i]) continue;
        // Among equal values, enforce a fixed order: i may only be placed if the
        // identical value at i-1 is ALREADY placed. Kills mirrored duplicates.
        if (i > 0 && a[i] == a[i - 1] && !used[i - 1]) continue;
        used[i] = true;  cur.push_back(a[i]);
        permuteUniqueRec(a, used, cur, out);
        cur.pop_back();  used[i] = false;
    }
}

vector<vector<int>> permuteUnique(vector<int> a) {
    sort(a.begin(), a.end());           // MANDATORY: equals must be adjacent
    vector<vector<int>> out; vector<int> cur;
    vector<bool> used(a.size(), false);
    permuteUniqueRec(a, used, cur, out);
    return out;
}

void beautifulRec(int n, int pos, vector<bool>& used, int& count) {
    if (pos > n) { ++count; return; }        // filled every position
    for (int v = 1; v <= n; ++v) {
        if (used[v]) continue;
        // PRUNE HERE: reject the moment the pair (pos, v) is invalid
        if (v % pos != 0 && pos % v != 0) continue;
        used[v] = true;
        beautifulRec(n, pos + 1, used, count);
        used[v] = false;
    }
}

int countArrangement(int n) {
    vector<bool> used(n + 1, false);
    int count = 0;
    beautifulRec(n, 1, used, count);          // positions are 1-indexed
    return count;
}

