def count_arrangement(n: int) -> int:
    used = [False] * (n + 1)
    count = 0

    def rec(pos):
        nonlocal count
        if pos > n:
            count += 1          # filled every position
            return
        for v in range(1, n + 1):
            if used[v]:
                continue
            # PRUNE HERE: reject the moment the pair (pos, v) is invalid
            if v % pos and pos % v:
                continue
            used[v] = True
            rec(pos + 1)
            used[v] = False

    rec(1)                      # positions are 1-indexed
    return count

