bool isPal(const string& s, int l, int r) {
    while (l < r) if (s[l++] != s[r--]) return false;
    return true;
}

void partitionRec(const string& s, int start, vector<string>& cur,
                  vector<vector<string>>& out) {
    if (start == (int)s.size()) { out.push_back(cur); return; }
    for (int end = start; end < (int)s.size(); ++end) {
        if (!isPal(s, start, end)) continue;          // only palindromic prefixes branch
        cur.push_back(s.substr(start, end - start + 1));
        partitionRec(s, end + 1, cur, out);
        cur.pop_back();
    }
}

vector<vector<string>> partition(const string& s) {
    vector<vector<string>> out; vector<string> cur;
    partitionRec(s, 0, cur, out);
    return out;
}

