def is_pal(s: str, l: int, r: int) -> bool:
    while l < r:
        if s[l] != s[r]:
            return False
        l += 1
        r -= 1
    return True


def partition(s: str) -> list:
    out, cur = [], []

    def rec(start):
        if start == len(s):
            out.append(cur[:])
            return
        for end in range(start, len(s)):
            if not is_pal(s, start, end):
                continue                    # only palindromic prefixes branch
            cur.append(s[start:end + 1])
            rec(end + 1)
            cur.pop()

    rec(0)
    return out

