void mazeRec(vector<vector<int>>& g, int r, int c, string& path,
             vector<string>& out) {
    int n = (int)g.size();
    if (r == n - 1 && c == n - 1) { out.push_back(path); return; }
    // D, L, R, U -- this order makes the output lexicographically sorted
    static const int dr[4] = {1, 0, 0, -1};
    static const int dc[4] = {0, -1, 1, 0};
    static const char dir[4] = {'D', 'L', 'R', 'U'};

    g[r][c] = 0;                              // MARK visited (block the cell)
    for (int k = 0; k < 4; ++k) {
        int nr = r + dr[k], nc = c + dc[k];
        if (nr < 0 || nc < 0 || nr >= n || nc >= n || g[nr][nc] == 0) continue;
        path.push_back(dir[k]);
        mazeRec(g, nr, nc, path, out);
        path.pop_back();
    }
    g[r][c] = 1;                              // UNMARK -- other paths may reuse it
}

vector<string> findPaths(vector<vector<int>> g) {
    vector<string> out; string path;
    if (g.empty() || g[0][0] == 0) return out;
    mazeRec(g, 0, 0, path, out);
    return out;
}

bool wordRec(vector<vector<char>>& b, const string& w, int r, int c, int idx) {
    if (idx == (int)w.size()) return true;              // whole word matched
    if (r < 0 || c < 0 || r >= (int)b.size() || c >= (int)b[0].size()) return false;
    if (b[r][c] != w[idx]) return false;

    char saved = b[r][c];
    b[r][c] = '#';                                       // block this cell
    bool found = wordRec(b, w, r + 1, c, idx + 1) ||
                 wordRec(b, w, r - 1, c, idx + 1) ||
                 wordRec(b, w, r, c + 1, idx + 1) ||
                 wordRec(b, w, r, c - 1, idx + 1);
    b[r][c] = saved;                                     // RESTORE
    return found;
}

bool exist(vector<vector<char>> board, const string& word) {
    for (int r = 0; r < (int)board.size(); ++r)
        for (int c = 0; c < (int)board[0].size(); ++c)
            if (wordRec(board, word, r, c, 0)) return true;
    return false;
}

