def exist(board: list, word: str) -> bool:
    if not board or not board[0] or not word:
        return bool(word) is False
    b = [row[:] for row in board]
    rows, cols = len(b), len(b[0])

    def rec(r, c, idx):
        if idx == len(word):
            return True                  # whole word matched
        if r < 0 or c < 0 or r >= rows or c >= cols:
            return False
        if b[r][c] != word[idx]:
            return False
        saved = b[r][c]
        b[r][c] = "#"                    # block this cell
        found = (rec(r + 1, c, idx + 1) or rec(r - 1, c, idx + 1) or
                 rec(r, c + 1, idx + 1) or rec(r, c - 1, idx + 1))
        b[r][c] = saved                  # RESTORE
        return found

    return any(rec(r, c, 0) for r in range(rows) for c in range(cols))
